text:
& label {
  align-items: center;
  border-radius: 36px;
  border: 1px solid transparent;
  cursor: pointer;
  display: flex;
  flex: 1;
  gap: 3px;
  block-size: 24px;
  margin: 3px 3px;
  z-index: 1;
  justify-content: center;
  padding-inline: 6px;
  overflow: hidden;

  &:hover {
    background-color: var(--color-surface-border);
  }

  & span {
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
  }

  img {
    -moz-context-properties: fill, stroke;
    color: transparent;
    fill: transparent;
    stroke: var(--icon-stroke);
    transition: all 0.2s ease-out;
    inline-size: 16px;
    block-size: 16px;
    display: none;
  }
}
